two-sum-iv-input-is-a-bst:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
        seen = set()
        def dfs(n):
            if not n: return False
            if k - n.val in seen: return True
            seen.add(n.val)
            return dfs(n.left) or dfs(n.right)
        return dfs(root)

univalued-binary-tree:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isUnivalTree(self, root: Optional[TreeNode]) -> bool:
        def dfs(n, v):
            if not n: return True
            return n.val == v and dfs(n.left, v) and dfs(n.right, v)
        return dfs(root, root.val)

leaf-similar-trees:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        def leaves(n):
            if not n: return []
            if not n.left and not n.right: return [n.val]
            return leaves(n.left) + leaves(n.right)
        return leaves(root1) == leaves(root2)

longest-continuous-increasing-subsequenc:
class Solution:
    def findLengthOfLCIS(self, nums: List[int]) -> int:
        if not nums: return 0
        best = cur = 1
        for i in range(1, len(nums)):
            cur = cur + 1 if nums[i] > nums[i-1] else 1
            best = max(best, cur)
        return best

valid-palindrome-ii:
class Solution:
    def validPalindrome(self, s: str) -> bool:
        def is_pal(lo, hi):
            while lo < hi:
                if s[lo] != s[hi]: return False
                lo += 1; hi -= 1
            return True
        i, j = 0, len(s) - 1
        while i < j:
            if s[i] != s[j]:
                return is_pal(i+1, j) or is_pal(i, j-1)
            i += 1; j -= 1
        return True

dominant-index:
class Solution:
    def dominantIndex(self, nums: List[int]) -> int:
        m = max(nums)
        return nums.index(m) if all(m >= 2 * n for n in nums if n != m) else -1

prime-number-of-set-bits-in-binary-repre:
class Solution:
    def countPrimeSetBits(self, left: int, right: int) -> int:
        primes = {2, 3, 5, 7, 11, 13, 17, 19}
        return sum(1 for n in range(left, right + 1) if bin(n).count('1') in primes)

