class Solution:
    def isToeplitzMatrix(self, matrix: List[List[int]]) -> bool:
        return all(matrix[i][j] == matrix[i-1][j-1] for i in range(1, len(matrix)) for j in range(1, len(matrix[0])))

shortest-completing-word:
class Solution:
    def shortestCompletingWord(self, licensePlate: str, words: List[str]) -> str:
        need = {}
        for ch in licensePlate.lower():
            if ch.isalpha(): need[ch] = need.get(ch, 0) + 1
        def ok(w):
            c = {}
            for ch in w: c[ch] = c.get(ch, 0) + 1
            return all(c.get(k, 0) >= v for k, v in need.items())
        return min([w for w in words if ok(w)], key=len)

one-bit-and-2-bit-characters:
class Solution:
    def isOneBitCharacter(self, bits: List[int]) -> bool:
        i = 0
        while i < len(bits) - 1:
            i += 2 if bits[i] else 1
        return i == len(bits) - 1

longest-word-in-dictionary:
class Solution:
    def longestWord(self, words: List[str]) -> str:
        words.sort()
        built = {''}
        best = ''
        for w in words:
            if w[:-1] in built:
                built.add(w)
                if len(w) > len(best): best = w
        return best

employee-importance:
class Solution:
    def getImportance(self, employees: List['Employee'], id: int) -> int:
        m = {e.id: e for e in employees}
        def dfs(i):
            e = m[i]
            return e.importance + sum(dfs(s) for s in e.subordinates)
        return dfs(id)
